/**
 * Skill Registry - 内置技能注册系统
 * 提供 Agent 无需 MCP 即可使用的核心技能
 */

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import axios from 'axios';

export class SkillRegistry {
  constructor(agent) {
    this.agent = agent;
    this.skills = new Map();
  }

  /**
   * 注册所有内置技能
   */
  registerBuiltinSkills() {
    // 代码执行技能
    this.register('code_execute', {
      description: '执行代码片段并返回结果',
      parameters: {
        type: 'object',
        properties: {
          language: { type: 'string', description: '编程语言: python, javascript, shell' },
          code: { type: 'string', description: '要执行的代码' }
        },
        required: ['language', 'code']
      },
      handler: this._executeCode.bind(this)
    });

    // 文件操作技能
    this.register('file_read', {
      description: '读取文件内容',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: '文件路径' },
          encoding: { type: 'string', description: '编码', default: 'utf-8' }
        },
        required: ['path']
      },
      handler: this._readFile.bind(this)
    });

    this.register('file_write', {
      description: '写入文件',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: '文件路径' },
          content: { type: 'string', description: '文件内容' },
          encoding: { type: 'string', description: '编码', default: 'utf-8' }
        },
        required: ['path', 'content']
      },
      handler: this._writeFile.bind(this)
    });

    this.register('file_search', {
      description: '在目录中搜索文件',
      parameters: {
        type: 'object',
        properties: {
          directory: { type: 'string', description: '搜索目录' },
          pattern: { type: 'string', description: '搜索模式 (glob)' },
          content: { type: 'string', description: '搜索文件内容 (regex)' }
        },
        required: ['directory']
      },
      handler: this._searchFiles.bind(this)
    });

    // HTTP 请求技能
    this.register('http_request', {
      description: '发送 HTTP 请求',
      parameters: {
        type: 'object',
        properties: {
          url: { type: 'string', description: '请求 URL' },
          method: { type: 'string', description: 'HTTP 方法', default: 'GET' },
          headers: { type: 'object', description: '请求头' },
          body: { type: 'string', description: '请求体' }
        },
        required: ['url']
      },
      handler: this._httpRequest.bind(this)
    });

    // 系统命令技能
    this.register('shell_execute', {
      description: '执行 shell 命令',
      parameters: {
        type: 'object',
        properties: {
          command: { type: 'string', description: 'Shell 命令' },
          cwd: { type: 'string', description: '工作目录' },
          timeout: { type: 'number', description: '超时时间(ms)', default: 30000 }
        },
        required: ['command']
      },
      handler: this._shellExecute.bind(this)
    });

    // 数据处理技能
    this.register('data_transform', {
      description: '数据格式转换 (JSON/CSV/YAML/Markdown)',
      parameters: {
        type: 'object',
        properties: {
          input: { type: 'string', description: '输入数据' },
          from_format: { type: 'string', description: '源格式' },
          to_format: { type: 'string', description: '目标格式' }
        },
        required: ['input', 'from_format', 'to_format']
      },
      handler: this._dataTransform.bind(this)
    });

    // 文本分析技能
    this.register('text_analyze', {
      description: '文本分析 (统计、提取、摘要)',
      parameters: {
        type: 'object',
        properties: {
          text: { type: 'string', description: '要分析的文本' },
          analysis_type: { type: 'string', description: '分析类型: stats, extract_keywords, summarize' }
        },
        required: ['text', 'analysis_type']
      },
      handler: this._textAnalyze.bind(this)
    });

    // 数学计算技能
    this.register('math_calculate', {
      description: '数学表达式计算',
      parameters: {
        type: 'object',
        properties: {
          expression: { type: 'string', description: '数学表达式' }
        },
        required: ['expression']
      },
      handler: this._mathCalculate.bind(this)
    });

    // 时间工具技能
    this.register('time_tool', {
      description: '时间相关操作',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', description: '操作: now, format, diff, add' },
          timezone: { type: 'string', description: '时区' },
          format: { type: 'string', description: '格式字符串' }
        },
        required: ['action']
      },
      handler: this._timeTool.bind(this)
    });

    // JSON/数据查询技能
    this.register('json_query', {
      description: 'JSON 数据查询 (JSONPath)',
      parameters: {
        type: 'object',
        properties: {
          data: { type: 'string', description: 'JSON 数据' },
          query: { type: 'string', description: '查询路径 (点分隔)' }
        },
        required: ['data', 'query']
      },
      handler: this._jsonQuery.bind(this)
    });

    // ==========================================
    // Data Analysis 技能组 (参考 anthropics/skills data-analysis)
    // ==========================================

    // Excel/CSV 文件读取
    this.register('excel_read', {
      description: '读取 Excel/CSV 文件，返回数据概览（行数、列名、数据类型、前N行预览）',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Excel/CSV 文件路径' },
          sheet: { type: 'string', description: '工作表名（仅Excel），默认第一个表' },
          preview_rows: { type: 'number', description: '预览行数，默认5' }
        },
        required: ['path']
      },
      handler: this._excelRead.bind(this)
    });

    // 数据清洗
    this.register('data_clean', {
      description: '数据清洗：去重、填充缺失值、删除异常行、类型转换、列重命名',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Excel/CSV 文件路径' },
          sheet: { type: 'string', description: '工作表名（仅Excel）' },
          operations: {
            type: 'array',
            description: '清洗操作列表',
            items: {
              type: 'object',
              properties: {
                type: { type: 'string', description: '操作类型: drop_na, fill_na, drop_duplicates, rename_column, filter_rows, convert_type' },
                column: { type: 'string', description: '目标列名' },
                value: { description: '填充值或过滤条件' },
                new_name: { type: 'string', description: '新列名（rename_column用）' },
                target_type: { type: 'string', description: '目标类型: int, float, str (convert_type用)' }
              },
              required: ['type']
            }
          },
          output_path: { type: 'string', description: '清洗后保存路径' }
        },
        required: ['path', 'operations']
      },
      handler: this._dataClean.bind(this)
    });

    // 数据分析
    this.register('data_analyze', {
      description: '数据分析：描述统计、分组聚合、相关性分析、交叉表',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Excel/CSV 文件路径' },
          sheet: { type: 'string', description: '工作表名（仅Excel）' },
          analysis_type: { type: 'string', description: '分析类型: describe, groupby, correlation, crosstab, value_counts' },
          column: { type: 'string', description: '目标列名' },
          group_by: { type: 'string', description: '分组列名（groupby用）' },
          agg_func: { type: 'string', description: '聚合函数: mean, sum, count, min, max, std（groupby用）' },
          column2: { type: 'string', description: '第二列（correlation/crosstab用）' }
        },
        required: ['path', 'analysis_type']
      },
      handler: this._dataAnalyze.bind(this)
    });

    // 数据可视化
    this.register('data_visualize', {
      description: '数据可视化：柱状图、折线图、散点图、饼图、直方图、热力图等',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Excel/CSV 文件路径' },
          sheet: { type: 'string', description: '工作表名（仅Excel）' },
          chart_type: { type: 'string', description: '图表类型: bar, line, scatter, pie, histogram, heatmap, box' },
          x_column: { type: 'string', description: 'X轴列名' },
          y_column: { type: 'string', description: 'Y轴列名（scatter/heatmap用）' },
          value_column: { type: 'string', description: '数值列名（pie用）' },
          label_column: { type: 'string', description: '标签列名（pie用）' },
          title: { type: 'string', description: '图表标题' },
          output_path: { type: 'string', description: '图片保存路径（默认 ./output/chart.png）' }
        },
        required: ['path', 'chart_type']
      },
      handler: this._dataVisualize.bind(this)
    });

    // 报表生成
    this.register('report_generate', {
      description: '生成数据分析报表（Markdown/HTML），包含数据概览、统计摘要、图表引用',
      parameters: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Excel/CSV 文件路径' },
          sheet: { type: 'string', description: '工作表名（仅Excel）' },
          title: { type: 'string', description: '报表标题' },
          format: { type: 'string', description: '输出格式: markdown, html', default: 'markdown' },
          include_charts: { type: 'boolean', description: '是否包含图表（需先生成）', default: false },
          output_path: { type: 'string', description: '报表保存路径' }
        },
        required: ['path']
      },
      handler: this._reportGenerate.bind(this)
    });

    // ==========================================
    // Academic Research (ARS) 技能
    // ==========================================

    // 顶会论文模板
    this.register('ars_conference_templates', {
      description: '顶会论文模板生成器 - 内置 NeurIPS/ICML/ICLR/AAAI/ACL/CVPR/EMNLP/KDD/IJCAI 模板，支持 LaTeX 骨架生成、格式校验、审稿标准查询',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', description: '操作: list, get, generate, compare, validate, criteria' },
          conference: { type: 'string', description: '会议简称: neurips, icml, iclr, aaai, acl, cvpr, emnlp, kdd, ijcai' },
          conference1: { type: 'string', description: '比较时第一个会议' },
          conference2: { type: 'string', description: '比较时第二个会议' },
          title: { type: 'string', description: '论文标题 (generate 时使用)' },
          authors: { type: 'string', description: '作者列表，逗号分隔 (generate 时使用)' },
          abstract: { type: 'string', description: '摘要内容 (generate 时使用)' },
          sections: { type: 'array', items: { type: 'string' }, description: '论文章节列表 (validate 时使用)' }
        },
        required: ['action']
      },
      handler: this._arsConferenceTemplates.bind(this)
    });

    // 5步引用验证
    this.register('ars_citation_verifier', {
      description: '5步引用验证防幻觉系统 - 存在性检查/准确性验证/相关性评估/时效性检查/格式一致性，支持 APA/IEEE/GB-T7714/MLA/Chicago/ACM',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', description: '操作: verify, step, formats, report' },
          citations: { type: 'array', items: { type: 'object' }, description: '引用列表' },
          step: { type: 'number', description: '单步验证步骤编号 1-5 (step 操作时使用)' },
          topic: { type: 'string', description: '论文主题 (用于相关性评估)' },
          abstract: { type: 'string', description: '论文摘要 (用于相关性评估)' },
          claims: { type: 'array', items: { type: 'string' }, description: '论文中使用引用的声明列表' },
          style: { type: 'string', description: '引用格式: apa, ieee, gb_t7714, mla, chicago, acm' }
        },
        required: ['action']
      },
      handler: this._arsCitationVerifier.bind(this)
    });

    console.log('[Skills] 已注册 ' + this.skills.size + ' 个内置技能');
  }

  register(name, skill) {
    this.skills.set(name, skill);
  }

  async execute(name, args) {
    const skill = this.skills.get(name);
    if (!skill) {
      throw new Error('技能 ' + name + ' 不存在');
    }
    return await skill.handler(args);
  }

  // === 技能实现 ===

  async _executeCode(args) {
    const { language, code } = args;
    try {
      let cmd;
      switch (language) {
        case 'python':
          cmd = 'python -c "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'javascript':
        case 'js':
          cmd = 'node -e "' + code.replace(/"/g, '\"') + '"';
          break;
        case 'shell':
          cmd = code;
          break;
        default:
          throw new Error('不支持的语言: ' + language);
      }
      const result = execSync(cmd, { timeout: 30000, encoding: 'utf-8' });
      return { success: true, output: result };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _readFile(args) {
    const { path: filePath, encoding } = args;
    try {
      const content = fs.readFileSync(filePath, encoding || 'utf-8');
      return { success: true, content };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _writeFile(args) {
    const { path: filePath, content, encoding } = args;
    try {
      const dir = path.dirname(filePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      fs.writeFileSync(filePath, content, encoding || 'utf-8');
      return { success: true, path: filePath };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _searchFiles(args) {
    const { directory, pattern, content } = args;
    try {
      let cmd = 'dir /s /b';
      if (pattern) cmd += ' "' + directory + '\\' + pattern + '"';
      else cmd += ' "' + directory + '"';

      const result = execSync(cmd, { timeout: 10000, encoding: 'utf-8' });
      let files = result.trim().split('\n').filter(Boolean);

      if (content) {
        const contentRegex = new RegExp(content, 'i');
        files = files.filter(f => {
          try {
            const fileContent = fs.readFileSync(f, 'utf-8');
            return contentRegex.test(fileContent);
          } catch { return false; }
        });
      }

      return { success: true, files: files.slice(0, 50) };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _httpRequest(args) {
    const { url, method, headers, body } = args;
    try {
      const config = {
        method: (method || 'GET').toUpperCase(),
        url,
        headers: headers || {},
        timeout: 30000
      };
      if (body && config.method !== 'GET') {
        config.data = body;
      }
      const response = await axios(config);
      return {
        success: true,
        status: response.status,
        data: typeof response.data === 'string' ? response.data : JSON.stringify(response.data)
      };
    } catch (error) {
      return { success: false, error: error.message, status: error.response?.status };
    }
  }

  async _shellExecute(args) {
    const { command, cwd, timeout } = args;
    try {
      const result = execSync(command, {
        timeout: timeout || 30000,
        encoding: 'utf-8',
        cwd: cwd || process.cwd()
      });
      return { success: true, output: result };
    } catch (error) {
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _dataTransform(args) {
    // 简化的数据转换
    const { input, from_format, to_format } = args;
    try {
      let data;
      if (from_format === 'json') {
        data = JSON.parse(input);
      } else {
        data = input;
      }

      if (to_format === 'json') {
        return { success: true, result: JSON.stringify(data, null, 2) };
      } else if (to_format === 'markdown') {
        if (Array.isArray(data)) {
          let md = '| # | ' + Object.keys(data[0] || {}).join(' | ') + ' |\n';

          md += '|---|' + Object.keys(data[0] || {}).map(() => '---').join('|') + '|\n';

          data.forEach((row, i) => {
            md += '| ' + (i + 1) + ' | ' + Object.values(row).join(' | ') + ' |\n';

          });
          return { success: true, result: md };
        }
        return { success: true, result: '```json\n' + JSON.stringify(data, null, 2) + '\n```' };
      }

      return { success: true, result: String(data) };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _textAnalyze(args) {
    const { text, analysis_type } = args;
    try {
      switch (analysis_type) {
        case 'stats':
          return {
            success: true,
            result: {
              characters: text.length,
              words: text.split(/\s+/).filter(Boolean).length,
              lines: text.split('\n').length,
              sentences: text.split(/[.!?]+/).filter(Boolean).length
            }
          };
        case 'extract_keywords':
          const words = text.toLowerCase().match(/[a-zA-Z一-龥]+/g) || [];
          const freq = {};
          words.forEach(w => { freq[w] = (freq[w] || 0) + 1; });
          const keywords = Object.entries(freq)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 20)
            .map(([word, count]) => ({ word, count }));
          return { success: true, result: keywords };
        default:
          return { success: false, error: '不支持的分析类型: ' + analysis_type };
      }
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _mathCalculate(args) {
    const { expression } = args;
    try {
      // 安全的数学计算 - 只允许数字和基本运算符
      if (!/^[0-9+\-*/().%\s^]+$/.test(expression)) {
        throw new Error('表达式包含不允许的字符');
      }
      const safeExpr = expression.replace(/\^/g, '**');
      const result = Function('"use strict"; return (' + safeExpr + ')')();
      return { success: true, result };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  async _timeTool(args) {
    const { action, timezone, format: fmt } = args;
    const now = new Date();
    switch (action) {
      case 'now':
        return { success: true, result: now.toISOString(), local: now.toLocaleString('zh-CN') };
      case 'format':
        return { success: true, result: now.toLocaleString('zh-CN', { timeZone: timezone }) };
      default:
        return { success: false, error: '不支持的操作: ' + action };
    }
  }

  async _jsonQuery(args) {
    const { data, query } = args;
    try {
      let obj = typeof data === 'string' ? JSON.parse(data) : data;
      const parts = query.split('.');
      for (const part of parts) {
        if (obj[part] !== undefined) {
          obj = obj[part];
        } else {
          return { success: false, error: '路径不存在: ' + part };
        }
      }
      return { success: true, result: obj };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }

  // ==========================================
  // Data Analysis 技能实现
  // 通过调用独立 Python 脚本执行，避免 eval/exec
  // ==========================================

  /**
   * 通用 Python 脚本执行器 - 仅用于 data-analysis 模块
   * 调用 scripts/ 目录下的预定义脚本，不执行任意代码
   */
  _runDataScript(scriptName, args) {
    const scriptPath = path.join(process.cwd(), 'scripts', scriptName);
    const argsJson = JSON.stringify(args);
    // 使用临时文件传递参数，避免命令行注入
    const tmpFile = path.join(process.cwd(), 'data', '.tmp_args.json');
    fs.mkdirSync(path.dirname(tmpFile), { recursive: true });
    fs.writeFileSync(tmpFile, argsJson, 'utf-8');
    try {
      const result = execSync(
        'python "' + scriptPath + '" "' + tmpFile + '"',
        { timeout: 60000, encoding: 'utf-8', cwd: process.cwd() }
      );
      // 清理临时文件
      try { fs.unlinkSync(tmpFile); } catch {}
      return JSON.parse(result);
    } catch (error) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _excelRead(args) {
    return this._runDataScript('excel_read.py', args);
  }

  async _dataClean(args) {
    return this._runDataScript('data_clean.py', args);
  }

  async _dataAnalyze(args) {
    return this._runDataScript('data_analyze.py', args);
  }

  async _dataVisualize(args) {
    return this._runDataScript('data_visualize.py', args);
  }

  async _reportGenerate(args) {
    return this._runDataScript('report_generate.py', args);
  }

  // ==========================================
  // Academic Research (ARS) 技能实现
  // 通过调用独立 Python 脚本执行
  // ==========================================

  /**
   * 通用 Python 脚本执行器 - 用于 ARS 模块
   */
  _runARSScript(scriptName, args) {
    const scriptPath = path.join(process.cwd(), 'scripts', scriptName);
    const argsJson = JSON.stringify(args);
    const tmpFile = path.join(process.cwd(), 'data', '.tmp_ars_args.json');
    fs.mkdirSync(path.dirname(tmpFile), { recursive: true });
    fs.writeFileSync(tmpFile, argsJson, 'utf-8');
    try {
      const result = execSync(
        'python "' + scriptPath + '" "' + tmpFile + '"',
        { timeout: 60000, encoding: 'utf-8', cwd: process.cwd() }
      );
      try { fs.unlinkSync(tmpFile); } catch {}
      return JSON.parse(result);
    } catch (error) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { success: false, error: error.message, stderr: error.stderr?.toString() };
    }
  }

  async _arsConferenceTemplates(args) {
    return this._runARSScript('ars_conference_templates.py', args);
  }

  async _arsCitationVerifier(args) {
    return this._runARSScript('ars_citation_verifier.py', args);
  }

  /**
   * 获取所有技能的 OpenAI 工具格式
   */
  getToolsAsOpenAIFormat() {
    const tools = [];
    for (const [name, skill] of this.skills) {
      tools.push({
        type: 'function',
        function: {
          name: 'skill__' + name,
          description: skill.description,
          parameters: skill.parameters
        }
      });
    }
    return tools;
  }
}

/**
 * Memory Manager - 持久记忆系统
 * 使用 JSON 文件存储（零编译依赖，无需 C++ 工具链）
 */

import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';
import crypto from 'crypto';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export class MemoryManager {
  constructor() {
    this.dataDir = path.join(__dirname, '..', 'data');
    this.memoriesPath = path.join(this.dataDir, 'memories.json');
    this.entitiesPath = path.join(this.dataDir, 'entities.json');
    this.relationsPath = path.join(this.dataDir, 'relations.json');
    this.data = { memories: [], entities: [], relations: [] };
  }

  async init() {
    if (!fs.existsSync(this.dataDir)) {
      fs.mkdirSync(this.dataDir, { recursive: true });
    }
    this._load();
    console.log('[Memory] 记忆系统已初始化 (' + this.data.memories.length + ' 条记忆, ' + this.data.entities.length + ' 个实体)');
  }

  _load() {
    try {
      if (fs.existsSync(this.memoriesPath)) {
        this.data.memories = JSON.parse(fs.readFileSync(this.memoriesPath, 'utf-8'));
      }
      if (fs.existsSync(this.entitiesPath)) {
        this.data.entities = JSON.parse(fs.readFileSync(this.entitiesPath, 'utf-8'));
      }
      if (fs.existsSync(this.relationsPath)) {
        this.data.relations = JSON.parse(fs.readFileSync(this.relationsPath, 'utf-8'));
      }
    } catch (e) {
      console.warn('[Memory] 加载记忆文件失败，使用空数据: ' + e.message);
      this.data = { memories: [], entities: [], relations: [] };
    }
  }

  _saveMemories() {
    fs.writeFileSync(this.memoriesPath, JSON.stringify(this.data.memories, null, 2), 'utf-8');
  }

  _saveEntities() {
    fs.writeFileSync(this.entitiesPath, JSON.stringify(this.data.entities, null, 2), 'utf-8');
  }

  _saveRelations() {
    fs.writeFileSync(this.relationsPath, JSON.stringify(this.data.relations, null, 2), 'utf-8');
  }

  /**
   * 存储记忆
   */
  async remember(data) {
    const id = crypto.randomUUID();
    const content = typeof data === 'string' ? data : JSON.stringify(data);
    const type = data.type || 'general';
    const importance = data.importance || 0.5;
    const now = new Date().toISOString();

    const memory = {
      id,
      type,
      content,
      importance,
      created_at: now,
      accessed_at: now,
      access_count: 0
    };

    this.data.memories.push(memory);
    this._saveMemories();
    return id;
  }

  /**
   * 搜索记忆（关键词匹配）
   */
  async search(query, limit = 5) {
    const q = query.toLowerCase();
    const results = this.data.memories
      .filter(m => m.content.toLowerCase().includes(q))
      .sort((a, b) => (b.importance || 0) - (a.importance || 0) || new Date(b.created_at) - new Date(a.created_at))
      .slice(0, limit);

    // 更新访问计数
    for (const r of results) {
      r.access_count = (r.access_count || 0) + 1;
      r.accessed_at = new Date().toISOString();
    }
    this._saveMemories();

    return results.map(r => ({
      id: r.id,
      type: r.type,
      content: r.content,
      importance: r.importance,
      createdAt: r.created_at
    }));
  }

  /**
   * 获取最近记忆
   */
  async recallRecent(limit = 10) {
    return this.data.memories
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
      .slice(0, limit)
      .map(r => ({
        id: r.id,
        type: r.type,
        content: r.content,
        importance: r.importance,
        createdAt: r.created_at
      }));
  }

  /**
   * 获取重要记忆
   */
  async recallImportant(limit = 10) {
    return this.data.memories
      .sort((a, b) => (b.importance || 0) - (a.importance || 0) || new Date(b.created_at) - new Date(a.created_at))
      .slice(0, limit)
      .map(r => ({
        id: r.id,
        type: r.type,
        content: r.content,
        importance: r.importance,
        createdAt: r.created_at
      }));
  }

  /**
   * 添加实体
   */
  async addEntity(name, type, description, properties) {
    const id = crypto.randomUUID();
    const entity = {
      id,
      name,
      type,
      description: description || '',
      properties: properties || null,
      created_at: new Date().toISOString()
    };

    const existing = this.data.entities.findIndex(e => e.name === name);
    if (existing >= 0) {
      this.data.entities[existing] = entity;
    } else {
      this.data.entities.push(entity);
    }
    this._saveEntities();
    return id;
  }

  /**
   * 添加关系
   */
  async addRelation(sourceId, targetId, relationType, properties) {
    const id = crypto.randomUUID();
    this.data.relations.push({
      id,
      source_id: sourceId,
      target_id: targetId,
      relation_type: relationType,
      properties: properties || null,
      created_at: new Date().toISOString()
    });
    this._saveRelations();
    return id;
  }

  /**
   * 查询实体关系
   */
  async getEntityRelations(entityName) {
    const entity = this.data.entities.find(e => e.name === entityName);
    if (!entity) return [];

    return this.data.relations
      .filter(r => r.source_id === entity.id)
      .map(r => {
        const target = this.data.entities.find(e => e.id === r.target_id);
        return { ...r, target_name: target?.name || 'unknown', target_type: target?.type || 'unknown' };
      });
  }

  /**
   * 删除记忆
   */
  async forget(id) {
    this.data.memories = this.data.memories.filter(m => m.id !== id);
    this._saveMemories();
  }

  /**
   * 清除所有记忆
   */
  async clearAll() {
    this.data.memories = [];
    this.data.entities = [];
    this.data.relations = [];
    this._saveMemories();
    this._saveEntities();
    this._saveRelations();
  }

  /**
   * 获取统计信息
   */
  getStats() {
    return {
      memoryCount: this.data.memories.length,
      entityCount: this.data.entities.length,
      relationCount: this.data.relations.length
    };
  }

  async close() {
    console.log('[Memory] 记忆系统已关闭（已持久化到 JSON 文件）');
  }
}

/**
 * Resonix Agent Engine - 核心 Agent 引擎
 * 集成 LLM + MCP 工具调用 + 记忆系统 + 思维链
 */

import OpenAI from 'openai';
import { MCPClientManager } from './mcp-client.js';
import { MemoryManager } from './memory.js';
import { SkillRegistry } from './skills.js';
import { Logger } from './logger.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import chalk from 'chalk';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env') });

export class ResonixAgent {
  constructor(options = {}) {
    this.name = options.name || 'Resonix';
    this.model = options.model || process.env.OPENAI_MODEL || 'gpt-4o';
    this.maxIterations = options.maxIterations || 20;
    this.verbose = options.verbose !== false;

    // 初始化 LLM 客户端
    this.llm = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
      baseURL: process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1'
    });

    // 初始化子系统
    this.mcp = new MCPClientManager();
    this.memory = new MemoryManager();
    this.skills = new SkillRegistry(this);
    this.logger = new Logger();

    // 对话历史
    this.conversationHistory = [];
    this.systemPrompt = this._buildSystemPrompt();
  }

  _buildSystemPrompt() {
    return `你是 Resonix，一个专业级 AI Agent 助手。你拥有以下核心能力：

## 核心身份
- 你是一个强大的自主 Agent，能够独立完成复杂任务
- 你会主动思考、规划、执行，而不是被动等待指令
- 你拥有持久记忆，可以跨会话记住信息

## 内置工具（无需 MCP 服务器，直接可用）
- 文件操作: file_read, file_write, file_search
- 代码执行: code_execute (支持 Python/JavaScript/Shell)
- Shell 命令: shell_execute
- HTTP 请求: http_request
- 数据处理: data_transform, text_analyze, math_calculate
- 时间工具: time_tool, json_query
- 数据分析: excel_read, data_clean, data_analyze, data_visualize, report_generate
- 学术研究: ars_conference_templates, ars_citation_verifier

## MCP 工具（通过服务器名__工具名 格式调用）
当 MCP 服务器连接成功时，工具会自动出现在可用列表中。

## 工作原则
1. 先思考再行动 - 复杂问题先分步推理再执行
2. 善用记忆 - 重要信息存入 memory 系统
3. 主动搜索 - 不确定的信息主动用搜索工具查证
4. 安全第一 - 不执行危险操作，关键操作需确认
5. 结果导向 - 确保每个任务都有明确的完成标准
6. 防幻觉验证 - 学术引用必须经过 ars_citation_verifier 验证

## 工具调用格式
- MCP 工具: 服务器名__工具名（例如 filesystem__read_file）
- 内置技能: 直接使用技能名（例如 file_read, excel_read）`;
  }

  /**
   * 初始化 Agent
   */
  async init() {
    this.logger.info('正在初始化 Resonix Agent...');

    // 连接所有 MCP 服务器
    await this.mcp.connectAll();

    // 初始化记忆系统
    await this.memory.init();

    // 注册内置技能
    this.skills.registerBuiltinSkills();

    // 加载历史记忆
    const memories = await this.memory.recallRecent(10);
    if (memories.length > 0) {
      this.logger.info('已加载 ' + memories.length + ' 条历史记忆');
    }

    this.logger.success('Resonix Agent 初始化完成!');
    this._printStatus();
  }

  /**
   * 运行 Agent 主循环
   */
  async run(userMessage) {
    // 添加用户消息到历史
    this.conversationHistory.push({
      role: 'user',
      content: userMessage
    });

    // 检查是否需要先回忆相关记忆
    const relevantMemories = await this.memory.search(userMessage);
    if (relevantMemories.length > 0) {
      const memoryContext = '相关记忆:\n' + relevantMemories.map(m => '- ' + m.content).join('\n');
      this.conversationHistory.push({
        role: 'system',
        content: memoryContext
      });
    }

    let iteration = 0;
    let finalResponse = '';

    while (iteration < this.maxIterations) {
      iteration++;

      try {
        // 获取 MCP 工具 + 内置技能工具列表
        const mcpTools = this.mcp.getToolsAsOpenAIFormat();
        const skillTools = this.skills.getToolsAsOpenAIFormat();
        const allTools = [...mcpTools, ...skillTools];

        // 调用 LLM
        const response = await this.llm.chat.completions.create({
          model: this.model,
          messages: [
            { role: 'system', content: this.systemPrompt },
            ...this.conversationHistory
          ],
          tools: allTools.length > 0 ? allTools : undefined,
          tool_choice: allTools.length > 0 ? 'auto' : undefined,
          temperature: 0.7,
          max_tokens: 4096
        });

        const message = response.choices[0].message;
        this.conversationHistory.push(message);

        // 如果没有工具调用，返回最终响应
        if (!message.tool_calls || message.tool_calls.length === 0) {
          finalResponse = message.content;
          break;
        }

        // 处理工具调用
        for (const toolCall of message.tool_calls) {
          const toolName = toolCall.function.name;
          const toolArgs = JSON.parse(toolCall.function.arguments);

          this.logger.toolCall(toolName, toolArgs);

          try {
            let result;

            // 处理 MCP 工具: 格式为 serverName__toolName
            if (toolName.includes('__')) {
              const [serverName, ...rest] = toolName.split('__');
              const actualToolName = rest.join('__');

              if (this.mcp.clients.has(serverName)) {
                result = await this.mcp.callTool(serverName, actualToolName, toolArgs);
              } else {
                throw new Error('MCP 服务器 "' + serverName + '" 未连接，请检查 mcp-config.json 配置');
              }
            } else {
              // 内置技能: 格式为 skill__skillName 或直接 skillName
              const skillName = toolName.startsWith('skill__') ? toolName.slice(7) : toolName;
              result = await this.skills.execute(skillName, toolArgs);
            }

            const resultStr = typeof result === 'string' ? result : JSON.stringify(result);
            this.logger.toolResult(toolName, resultStr);

            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: resultStr
            });

            // 重要结果存入记忆
            if (this._isWorthRemembering(toolName, resultStr)) {
              await this.memory.remember({
                type: 'tool_result',
                tool: toolName,
                query: userMessage,
                result: resultStr.substring(0, 500)
              });
            }

          } catch (error) {
            this.logger.error('工具调用失败 ' + toolName + ': ' + error.message);
            this.conversationHistory.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              content: '错误: ' + error.message
            });
          }
        }

      } catch (error) {
        this.logger.error('LLM 调用失败: ' + error.message);
        finalResponse = '抱歉，处理时出现错误: ' + error.message;
        break;
      }
    }

    if (iteration >= this.maxIterations) {
      finalResponse = '已达到最大迭代次数，任务可能未完全完成。';
    }

    // 保存对话到记忆
    await this.memory.remember({
      type: 'conversation',
      user: userMessage,
      assistant: finalResponse
    });

    return finalResponse;
  }

  /**
   * 判断结果是否值得记忆
   */
  _isWorthRemembering(toolName, result) {
    const memorableTools = [
      'file_write',
      'shell_execute',
      'code_execute'
    ];
    return memorableTools.some(t => toolName.startsWith(t));
  }

  /**
   * 打印状态
   */
  _printStatus() {
    const status = this.mcp.getStatus();
    console.log('\n' + chalk.cyan('========================================'));
    console.log(chalk.cyan('  Resonix Agent 状态面板'));
    console.log(chalk.cyan('========================================'));
    for (const [name, info] of Object.entries(status)) {
      const icon = info.status === 'connected' ? chalk.green('OK') : chalk.red('FAIL');
      console.log('  ' + icon + ' ' + chalk.bold(name) + ' (' + info.tools + ' tools) - ' + info.description);
    }
    console.log(chalk.cyan('========================================') + '\n');
  }

  /**
   * 关闭 Agent
   */
  async shutdown() {
    this.logger.info('正在关闭 Resonix Agent...');
    await this.mcp.disconnectAll();
    await this.memory.close();
    this.logger.success('Resonix Agent 已关闭');
  }
}

#!/usr/bin/env node

/**
 * Resonix Super Agent - 主入口
 * 交互式命令行 Agent
 */

import { ResonixAgent } from './agent.js';
import chalk from 'chalk';
import readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function printBanner() {
  console.log('');
  console.log(chalk.cyan('  ╔══════════════════════════════════════════╗'));
  console.log(chalk.cyan('  ║') + chalk.bold.white('       R E S O N I X   A G E N T        ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ║') + chalk.gray('     Professional AI Agent with MCP       ') + chalk.cyan('║'));
  console.log(chalk.cyan('  ╚══════════════════════════════════════════╝'));
  console.log('');
  console.log(chalk.gray('  命令:'));
  console.log(chalk.gray('    /status   - 查看 MCP 服务器状态'));
  console.log(chalk.gray('    /memory   - 查看记忆统计'));
  console.log(chalk.gray('    /skills   - 查看可用技能'));
  console.log(chalk.gray('    /clear    - 清除对话历史'));
  console.log(chalk.gray('    /help     - 显示帮助'));
  console.log(chalk.gray('    /exit     - 退出 Agent'));
  console.log('');
}

async function main() {
  printBanner();

  const agent = new ResonixAgent({
    name: 'Resonix',
    model: process.env.OPENAI_MODEL || 'gpt-4o'
  });

  console.log(chalk.yellow('正在初始化 Agent...'));
  try {
    await agent.init();
  } catch (error) {
    console.error(chalk.red('初始化失败: ' + error.message));
    console.log(chalk.yellow('提示: 请检查 .env 文件中的 API Key 配置'));
    console.log(chalk.yellow('你可以复制 .env.example 为 .env 并填入你的 API Key'));
  }

  console.log(chalk.green('
Agent 已就绪! 输入你的问题开始对话。
'));

  const prompt = () => {
    rl.question(chalk.bold.cyan('You> '), async (input) => {
      const trimmed = input.trim();

      if (!trimmed) {
        prompt();
        return;
      }

      // 处理命令
      if (trimmed.startsWith('/')) {
        const cmd = trimmed.toLowerCase();

        switch (cmd) {
          case '/exit':
          case '/quit':
            console.log(chalk.yellow('
正在关闭...'));
            await agent.shutdown();
            console.log(chalk.green('再见!'));
            process.exit(0);
            break;

          case '/status':
            const status = agent.mcp.getStatus();
            console.log(chalk.cyan('
=== MCP 服务器状态 ==='));
            for (const [name, info] of Object.entries(status)) {
              const icon = info.status === 'connected' ? chalk.green('OK') : chalk.red('FAIL');
              console.log('  ' + icon + ' ' + name + ' (' + info.tools + ' tools) - ' + info.description);
            }
            console.log('');
            break;

          case '/memory':
            const stats = agent.memory.getStats();
            console.log(chalk.cyan('
=== 记忆统计 ==='));
            console.log('  记忆条数: ' + stats.memoryCount);
            console.log('  实体数量: ' + stats.entityCount);
            console.log('  关系数量: ' + stats.relationCount);
            console.log('');
            break;

          case '/skills':
            console.log(chalk.cyan('
=== 内置技能 ==='));
            for (const [name, skill] of agent.skills.skills) {
              console.log('  ' + chalk.bold(name) + ' - ' + skill.description);
            }
            console.log(chalk.cyan('
=== MCP 工具 ==='));
            for (const [key, value] of agent.mcp.tools) {
              console.log('  ' + chalk.bold(key) + ' - ' + (value.tool.description || '').substring(0, 60));
            }
            console.log('');
            break;

          case '/clear':
            agent.conversationHistory = [];
            console.log(chalk.green('对话历史已清除'));
            break;

          case '/help':
            printBanner();
            break;

          default:
            console.log(chalk.red('未知命令: ' + trimmed));
            break;
        }

        prompt();
        return;
      }

      // 处理普通对话
      try {
        const response = await agent.run(trimmed);
        console.log('
' + chalk.bold.green('Resonix> ') + response + '
');
      } catch (error) {
        console.error(chalk.red('
错误: ' + error.message + '
'));
      }

      prompt();
    });
  };

  prompt();

  // 优雅退出
  process.on('SIGINT', async () => {
    console.log(chalk.yellow('
正在关闭...'));
    await agent.shutdown();
    console.log(chalk.green('再见!'));
    process.exit(0);
  });
}

main().catch(console.error);

import os, re

pkg_dir = os.path.join(os.environ.get("APPDATA", ""), "npm", "node_modules", "reasonix")

# Search for skill-related code in the main source files
skill_code = []
for root, dirs, files in os.walk(pkg_dir):
    dirs[:] = [d for d in dirs if d != "node_modules" and d != ".git" and d != "dashboard"]
    for f in files:
        if f.endswith((".js", ".mjs", ".cjs")):
            fpath = os.path.join(root, f)
            try:
                with open(fpath, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read()
                    # Look for skill-related function definitions and logic
                    if re.search(r'\bskill\b', content, re.IGNORECASE):
                        rel = os.path.relpath(fpath, pkg_dir)
                        size = os.path.getsize(fpath)
                        print("File: " + rel + " (" + str(size) + " bytes)")

                        # Find skill-related lines
                        lines = content.split("\n")
                        for i, line in enumerate(lines):
                            if re.search(r'(skill|/skill)', line, re.IGNORECASE):
                                stripped = line.strip()
                                if len(stripped) > 10 and len(stripped) < 300:
                                    skill_code.append((rel, i+1, stripped))
            except:
                pass

print("\n=== Skill-related code lines ===")
for rel, lineno, content in skill_code[:80]:
    print(rel + ":" + str(lineno) + " -> " + content[:200])
